	{ version = "1.5.5-beta.4", date = "2026-11-26", blocks = {
		{ "h", "Fixed: a ring's crossbar button ignored the mouse" },
		{ "b", "Clicking a crossbar button that opens a ring (or Healer mode) did nothing. Now a left click opens that ring right there, as a touch tap does: click a slot to use it, click outside to close. It follows the crossbar page you're on and works in combat.", 1 },
